head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

scwin.onpageload = function () {
    // 데이터는 dataList 정적 데이터로 세팅됨(추가 처리 없음)
};

// Cell td 요소의 실제 DOM textContent 조회 (공백 1 칸으로 정규화)
scwin.getCellText = function (gridObj, rowIndex, colIndex) {
    var gid = gridObj.id;
    var el = document.getElementById(gid + "_cell_" + rowIndex + "_" + colIndex);

    if (el == null) {
        var tdList = document.querySelectorAll("td[id*='" + gid + "_cell_" + rowIndex + "_" + colIndex + "']");
        el = tdList.length > 0 ? tdList[0] : null;
    }

    if (el == null) {
        return "(Cell 요소를 찾을 수 없음)";
    }

    return el.textContent.replace(/ /g, " ").replace(/\s+/g, " ").trim();
};

// Column 3 종(number / float / bigDecimal) 의 표시값을 기대값과 대조 출력
scwin.printRow = function (gridObj, rowIndex, strSource, strExpected) {
    var cols = [
        { idx: 0, id: "col_num", type: "number     " },
        { idx: 1, id: "col_float", type: "float      " },
        { idx: 2, id: "col_big", type: "bigDecimal " }
    ];

    scwin.setReturnValue("  -- 원본 데이터 : " + strSource + "  (기대 표시값 : " + strExpected + ")");

    for (var i = 0; i < cols.length; i++) {
        var col = cols[i];
        var strDom = scwin.getCellText(gridObj, rowIndex, col.idx);
        var strApi = gridObj.getCellDisplayData(rowIndex, col.id);

        scwin.setReturnValue("     dataType=" + col.type
            + "| 셀 DOM textContent : " + strDom
            + " | getCellDisplayData() : " + strApi
            + " | 기대 : " + strExpected
            + " -> " + (strDom === strExpected ? "정상" : "결함"));
    }
};

// [증상 ①] 마스크 왼쪽 일반문자 + 음수 : float 만 부호가 일반문자 앞으로 이탈
scwin.btn_sign_onclick = function () {
    scwin.setReturnValue("■ 증상 ① numberMask = \"" + grd_sign.options.numberMask + "\"");
    scwin.printRow(grd_sign, 0, "-1234.5678", "₩ -1,234.57 won");
    scwin.printRow(grd_sign, 1, "1234.5678", "₩ 1,234.57 won");
    scwin.setReturnValue("");
};

// [증상 ②] 정수 전용 마스크 : float 만 반올림 미적용
scwin.btn_round_onclick = function () {
    scwin.setReturnValue("■ 증상 ② numberMask = \"" + grd_noSuffix.options.numberMask + "\"");
    scwin.printRow(grd_noSuffix, 0, "-1234.5678", "-1,235");
    scwin.printRow(grd_noSuffix, 1, "1234.5678", "1,235");
    scwin.setReturnValue("");
};
